        public bool Create(FormulaViewModel frmVM)
        {
            //#region 
            //var lis_schema = frmVM.FormulaSchema.Split('&');
            //frmVM.MoalefeID = Convertlis_schema[0];
            //frmVM.FormulaSchema = "";
            //for(int i = 1; i < lis_schema.Length; i++)
            //{
            //    frmVM.FormulaSchema += lis_schema[i];
            //}
            //foreach

            //#endregion
            string Variablesid = "";
            foreach (var item in frmVM.VariablesId)
            {
                Variablesid = Variablesid + item.ToString() + ",";
            }

            tbFormula formula = new tbFormula
            {
                Frml_Formula = frmVM.FormulaView,
                Frml_IsActive = true,
                Frml_Schema = frmVM.FormulaSchema,
                Frml_Title = frmVM.Title,
                Frml_Priority = null,
                Frml_Variablesid = Variablesid,
                FKMoalefeDastMozdi = frmVM.MoalefeID

            };
            if (frmVM.MoalefeID == 0)
            {
                frmVM.MoalefeID = null;
            }

            if (FormulaRepo.Create(formula) == "True")
            {
                return true;
            }
            else
            {
                return false;
            }

        }




