                                    return "ثبت کردن مولفه با خطا مواجه شد";
                                }
                                break;
                            }
                        }
                        else
                        {
                            return "این شیت فاقد سطر می باشد";
                        }
                    }
                    else
                    {
                        return "هیچ شیتی در این اکسل وجود ندارد";
                    }
                    transaction.Commit();
                    return "با موفقیت انجام شد";
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return ex.Message;

                }
            }
        }

        public string GetDataFromExcel_FishtAEAD(HttpPostedFileBase MyExcelStream, int Basteh)
        {
            int mlfvlfsh_Year, mlfvlfsh_Month, malefe;
            float mlfvlfsh_Value;
            string name = "";
            List<tbMoalefeValueFish> IsFish = new List<tbMoalefeValueFish>();
            var user = db.tbUsers.ToList();
            var moalfe = db.tbContractMoalefeDastmozdi.ToList();
            var workbook = Telerik.Web.Spreadsheet.Workbook.Load(MyExcelStream.InputStream, System.IO.Path.GetExtension(MyExcelStream.FileName));
            var c = db.tbmoalfefishexcel.OrderByDescending(s => s.ID).FirstOrDefault();
            using (DbContextTransaction transaction = db.Database.BeginTransaction())
            {
                try
                {
                    var Count_Sheets = workbook.Sheets.Count;
                    if (Count_Sheets >= 1)
                    {
                        var sheet = workbook.Sheets[0];
                        var Rows = sheet.Rows;
                        if (Rows.Count >= 1)
                        {
                            foreach (var item in Rows)
                            {
                                if (item.Cells.Count != sheet.Rows[0].Cells.Count)
                                {
                                    return " خطای ارزیابی در سطر " + (item.Index + 1).ToString() + " رخ داده است. یکی از سلول های این ستون فاقد اطلاعات می باشد ";
                                    ;
                                }
                                var title = workbook.Sheets[0].Rows[0].Cells;
                                var List = workbook.Sheets[0].Rows;
                                var count = workbook.Sheets[0].Rows.Count();
                                if (count == 1)
                                {
                                    return "فایل اکسل فاقد اطلاعات می باشد";
                                }
                                for (int i = 1; i < count; i++)
                                {
                                    var row = workbook.Sheets[0].Rows[i];
                                    var Name = row.Cells[1];
                                    if (Name.Value != null)
                                    {
                                        malefe = (int)Name.Value;
                                    }
                                    else
                                    {
                                        return " لطفا ستون نام  سطر " + " ( " + i + " ) " + "را پر کنید ";
                                    }
                                    var year = row.Cells[2];
                                    if (year.Value != null)
                                    {
                                        mlfvlfsh_Year = (int)year.Value;
                                    }
                                    else
                                    {
                                        return " لطفا ستون نام  سطر " + " ( " + i + " ) " + "را پر کنید ";
                                    }
                                    var month = row.Cells[3];
                                    if (month.Value != null)
                                    {
                                        mlfvlfsh_Month = (int)month.Value;
                                    }
                                    else
                                    {
                                        return " لطفا ستون نام  سطر " + " ( " + i + " ) " + "را پر کنید ";
                                    }

                                    for (int j = 4; j < title.Count; j++)
                                    {

                                        var Name2 = workbook.Sheets[0].Rows[0].Cells[j];
                                        if (Name2.Value != null || Name2.Value.ToString() != "")
                                        {
                                            name = Name2.Value.ToString();
                                        }
                                        else
                                        {
                                            return " لطفا ستون نام  سطر " + " ( " + j + " ) " + "را پر کنید ";
                                        }
                                        var mlfvlfsh_Value2 = workbook.Sheets[0].Rows[i].Cells[j];
                                        if (float.TryParse(mlfvlfsh_Value2.Value.ToString(), out float result2))
                                        {
                                            mlfvlfsh_Value = result2; // Assuming month.Value is convertible to an integer.
                                        }
                                        else
                                        {
                                            return " لطفا ستون نام  سطر " + " ( " + j + " ) " + "را پر کنید ";
                                        }

                                        int userid2 = 0;
                                        var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                                        if (cookie_user != null)
                                        {
                                            var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                                            using (SaabEntities db = new SaabEntities())
                                            {
                                                var User = db.tbUsers.Where(p => p.usr_NationalCode.ToString() == nationalcode).FirstOrDefault();
                                                if (User != null)
                                                {
                                                    userid2 = User.usr_ID;
                                                }
                                            }
                                        }
                                        var c4 = db.tbReffrenceAccept.Where(p => p.FK_ReffrenceSaveLevel == Basteh).FirstOrDefault();

                                        var v = db.tbReffrenceAcceptLevel.Where(p => p.FK_ReffrenceAccept == c4.ID).FirstOrDefault();
                                        var b = db.tbReffrenceAcceptLevelUsers.Where(p => p.FK_ReffrenceAcceptLevel == v.ID).OrderByDescending(x => x.ID).Select(s => s.FK_User).FirstOrDefault();
                                        var FK_User = user.FirstOrDefault(p => p.usr_Personal_ID == malefe).usr_ID;
                                        var md_ID = moalfe.Where(p => p.md_Title.Contains(name)).Select(s => s.md_ID).FirstOrDefault();

                                        if (b == userid2)
                                        {

                                            tbMoalefeValueFish moalefe = new tbMoalefeValueFish

                                            {
                                                Finalaccept = true,
                                                FK_Moalefe = md_ID,
                                                mlfvlfsh_Submit = false,

                                                FK_User = FK_User,
                                                mlfvlfsh_Value = mlfvlfsh_Value,
                                                mlfvlfsh_Month = mlfvlfsh_Month,
                                                mlfvlfsh_Year = mlfvlfsh_Year,

                                                FK_EXCel = c.ID
                                            };
                                            IsFish.Add(moalefe);
                                            var r = db.tbUserSalaryDetail.Where(p => p.usrslrydtl_Month == mlfvlfsh_Month && p.usrslrydtl_Year == mlfvlfsh_Year).FirstOrDefault();
                                            if (r != null)
                                            {
                                                r.usrslrydtl_PerformanceAccept = true;
                                                db.SaveChanges();
                                            }

                                        }
                                        else
                                        {
                                            tbMoalefeValueFish moalefe = new tbMoalefeValueFish

                                            {
                                                FK_Moalefe = md_ID,
                                                mlfvlfsh_Submit = false,

                                                FK_User = FK_User,
                                                mlfvlfsh_Value = mlfvlfsh_Value,
                                                mlfvlfsh_Month = mlfvlfsh_Month,
                                                mlfvlfsh_Year = mlfvlfsh_Year,

                                                FK_EXCel = c.ID
                                            };
                                            IsFish.Add(moalefe);
                                        }

                                    }


                                }
                                if (!moalefeValueFishRepo.AddRange(IsFish))
                                {
                                    transaction.Rollback();
                                    return "ثبت کردن مولفه با خطا مواجه شد";
                                }
                                break;
                            }
                        }
                        else
                        {
                            return "این شیت فاقد سطر می باشد";
                        }
                    }
                    else
                    {
                        return "هیچ شیتی در این اکسل وجود ندارد";
                    }
                    transaction.Commit();
                    return "با موفقیت انجام شد";
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    return ex.Message;

                }
            }
        }

