        public bool Edit(FormulaViewModel frmVM)
        {
            string Variablesid = "";
            foreach (var item in frmVM.VariablesId)
            {
                Variablesid = Variablesid + item.ToString() + ",";
            }
            tbFormula formula = new tbFormula
            {
                Frml_Schema = frmVM.FormulaSchema,
                Frml_Formula = frmVM.FormulaView,
                Frml_Title = frmVM.Title,
                Frml_Variablesid = Variablesid,
                FKMoalefeDastMozdi = frmVM.MoalefeID,

            };
            if (FormulaRepo.Update(formula) == "True")
            {
                return true;
            }
            else
            {
                return false;
            }
        }
        [AuthorizeAAA]
        [HttpPost]
        public bool GetPriority(List<FormulaPriority> lstFormulaPriority)
        {
            try
            {
                foreach (var item in lstFormulaPriority)
                {
                    var formula = FormulaRepo.Find(item.FormulaID);
                    formula.Frml_Priority = item.Priority;
                    FormulaRepo.Update(formula);
                }

                return true;
            }
            catch (Exception)
            {
                return false;
            }

        }


