        public ActionResult view66()


        {
            int pymn = 30, month = 11, year = 1402, day = 1, city = 1, day2 = 30;

            // Initialize ViewModel
            ReportStatmentsViewModel sorat = new ReportStatmentsViewModel();
            sorat.Header_0 = new RSHeader(); // Initialize Header_0
            sorat.basket7 = new basket();
            sorat.basket9 = new basket9();
            sorat.basket10 = new basket10();
            sorat.Contracs_1 = new RSContract();
            sorat.AmalkerdEntezar_2 = new RSAmalkerdEntezar();
            sorat.AmalkerdEntezar_2.amalkerdEntezarSubCirties = new List<RSAmalkerdEntezarSubCirties>();
            // مقداردهی اولیه برای EnergyInformation
            sorat.Contracs_1.EnergyInformation = new RSContractInformation();
            sorat.Contracs_1.Baskets = new List<RSContractBasketsInformation>();
            sorat.ControlBasteks_4 = new RSControlBasteks();
            sorat.ControlBasteks_4.list_SooratVaziat = new List<RsSooratVaziat>();

            // Initialize Baskets
            // Retrieve data from database
            var KargozariName = db.tbPeymanContracts.Where(p => p.pec_ID == pymn && p.Inactive != true).FirstOrDefault();
            var city2 = db.tbCities.Where(p => p.ID == city).FirstOrDefault();
            var pric = db.tbPeymanContractPrice.Where(p => p.FKPeymanID == pymn).FirstOrDefault();
            var elhagh = db.tbPeymanElhaghie.Where(p => p.FK_PeymanID == pymn).FirstOrDefault();



            // Check if data is retrieved successfully
            if (KargozariName != null && city2 != null && pric != null)
            {
                // Assign values to ViewModel properties
                sorat.Header_0.Peymankar = KargozariName.pec_Title;
                sorat.Header_0.KargozariName = KargozariName.pec_BriefTitle;
                sorat.Header_0.KargozariCode = (int)KargozariName.pec_ProjectCode;
                sorat.Header_0.NameOfcubCities = city2.Name;

                // Format dates
                sorat.Header_0.FromDate = $"{day}/{month.ToString("00")}/{year}";
                sorat.Header_0.toDate = $"{day2}/{month.ToString("00")}/{year}";
                sorat.Header_0.numberOfSooratVaziat = month;
                sorat.Contracs_1.EnergyInformation.Base = pric.CountForPer;
                if (elhagh != null)
                {
                    sorat.Contracs_1.EnergyInformation.Elhaghie = "0";

                    // تبدیل مقدار رشته‌ای به عدد
                    int elhaghieValue = System.Convert.ToInt32(sorat.Contracs_1.EnergyInformation.Elhaghie);
                    int bacee = System.Convert.ToInt32(sorat.Contracs_1.EnergyInformation.Base);
                    int value = bacee - elhaghieValue;
                    // انجام عملیات ریاضی
                    sorat.Contracs_1.EnergyInformation.Final = System.Convert.ToString(value);






                    sorat.Contracs_1.PriceContractInformation.Base = pric.Price;
                    sorat.Contracs_1.PriceContractInformation.Elhaghie = elhagh.Price;
                    int elhaghieValue2 = (int)System.Convert.ToInt64(sorat.Contracs_1.PriceContractInformation.Base);
                    int bacee2 = (int)System.Convert.ToInt64(sorat.Contracs_1.PriceContractInformation.Elhaghie);
                    int value2 = bacee2 - elhaghieValue2;
                    sorat.Contracs_1.PriceContractInformation.Final = System.Convert.ToString(value2);
                    sorat.Contracs_1.PriceContractInformation.TaeedShode = "50000";
                    int taedtoint = System.Convert.ToInt32(sorat.Contracs_1.PriceContractInformation.Final);
                    int taedshode = System.Convert.ToInt32(sorat.Contracs_1.PriceContractInformation.TaeedShode);
                    int value3 = taedtoint - taedshode;
                    sorat.Contracs_1.PriceContractInformation.Mande = System.Convert.ToString(value3);

                }
                else
                {
                    sorat.Contracs_1.EnergyInformation.Elhaghie = "0";


                    decimal elhaghieValue = (decimal)System.Convert.ToInt64(sorat.Contracs_1.EnergyInformation.Elhaghie.Replace(",", ""));
                    string baseString = sorat.Contracs_1.EnergyInformation.Base;
                    baseString = Regex.Replace(baseString, "[^0-9.]", ""); // حذف همه کاراکترهای غیر عددی و نقطه
                    baseString = baseString.Trim();
                    decimal bacee = decimal.Parse(baseString);

                    decimal value = bacee - elhaghieValue;
                    // انجام عملیات ریاضی
                    sorat.Contracs_1.EnergyInformation.Final = System.Convert.ToString(value);





                    if (sorat.Contracs_1.PriceContractInformation != null)
                    {
                        // انجام عملیات مرتبط با sorat.Contracs_1.PriceContractInformation.Base
                        sorat.Contracs_1.PriceContractInformation.Base = pric.Price;
                    }
                    else
                    {
                        // ایجاد یک نمونه جدید از PriceContractInformation و تنظیم Base
                        sorat.Contracs_1.PriceContractInformation = new RSContractInformation();
                        sorat.Contracs_1.PriceContractInformation.Base = pric.Price;
                    }

                    sorat.Contracs_1.PriceContractInformation.Elhaghie = "0";
                    string elhaghieString2 = sorat.Contracs_1.PriceContractInformation.Elhaghie.Replace(",", "");
                    elhaghieString2 = elhaghieString2.Trim();
