        public ActionResult viewfishdasteh()
        {
            int month = 0; int year = 0;
            if (month == 0)
            {
                year = 1403;
                month = 12;
            }
            FunctionModel lstMoalefeexcel2 = new FunctionModel();

            lstMoalefeexcel2.year = new year();
            lstMoalefeexcel2.Dastehfish = new List<Dastehfish>();
            var linkpymn = db.Link_User_And_Peyman.Where(s => s.Status == true).ToList();
            var city = db.tbCities.ToList();

            var usr = db.tbUsers.ToList();
            foreach (var it in usr)
            {
                string shogl = "";
                string citynamef = "";

                string pymn = "";
                var findpymn = linkpymn.Where(s => s.FK_User_ID == it.usr_ID).FirstOrDefault();
                if (findpymn != null)
                {
                    pymn = findpymn.tbPeymanContracts.pec_Title;

                }
                var cityname = city.Where(s => s.ID == it.usr_City_Dutysystem).FirstOrDefault();
                if (cityname != null)
                {
                    citynamef = cityname.Name;

                }

                if (it.usr_job != null)
                {
                    shogl = it.tbjob.Name;
                }
                var Dastehfish = new Dastehfish
                {
                    pumn = pymn,
                    fullname = it.FullName,
                    Year = year,
                    Month = month,
                    city = citynamef,
                    shogl = shogl,
                    ID = it.usr_ID,

                    stringshogk = it.usr_Personal_ID.ToString()

                };



                lstMoalefeexcel2.Dastehfish.Add(Dastehfish);
            }
            return View("~/Areas/Salaries/Views/Formula/viewfishdasteh.cshtml", lstMoalefeexcel2);
        }
