                        if (item11.FK_User_ID.HasValue) // چک کردن برای مقدار null
                        {
                            us.Add(item11.FK_User_ID.Value); // استفاده از Value برای گرفتن مقدار int
                        }
                    }
                    long xx = 0;
                    var bb = db.tbSoratvaziat.Where(p => p.Fk_pymn == KargozariName.pec_ID && p.Final_accept == true).ToList();
                    var des = db.Descriptionsorat.Where(p => p.FK_Pymn == KargozariName.pec_ID).ToList();
                    long chamm = 0;
                    foreach (var v in us)
                    {
                        var d4 = dbfish.Where(p => p.FK_User == v && p.FK_Moalefe == eydipadash.md_ID).ToList();
                        foreach (var itt in d4)
                        {
                            xx += (long)(itt.mlfvlfsh_Value ?? 0);

                        }



                    }
                    foreach (var item99 in bb)
                    {
                        xx += item99.value ?? 0;
                        chamm += item99.gham ?? 0;
                    }
                    foreach (var item2 in des)
                    {
                        xx += item2.value ?? 0;
                    }

                    var sakb = db.tbDetermining_creditline
          .Where(p => p.Pyman_ID == KargozariName.pec_ID)
          .OrderByDescending(w => w.Determining_creditline_ID)
          .GroupBy(s => s.FK_creditline)
          .ToList();

                    double ent = 0; // Assuming ent is a long variable to accumulate the Creditorcredit values
                    foreach (var group in sakb)
                    {
                        // Access the Creditorcredit property of each group and accumulate it to ent
                        foreach (var item2 in group)
                        {
                            ent += item2.Creditorcredit ?? 0;
                        }
                    }
                    var ebtez2 = db.tbSoratvaziat.Where(p => p.Fk_pymn == KargozariName.pec_ID && p.Enerjy != null && p.nergh != null && p.Final_accept == true).ToList();
                    long enr3 = 0;
                    long gham = 0;
                    foreach (var item2 in ebtez2)
                    {
                        enr3 += item2.Enerjy ?? 0;
                        gham += item2.gham ?? 0;
                    }
                    var countForPerString = db.tbPeymanContractPrice
           .Where(p => p.FKPeymanID == KargozariName.pec_ID)
           .Select(p => p.Count)
           .FirstOrDefault();




                    long j = (long)countForPerString; // Default value



                    // Define custom number format settings
                    NumberFormatInfo numberFormat = new NumberFormatInfo();
                    numberFormat.NumberGroupSeparator = ",";
                    numberFormat.NumberDecimalSeparator = ".";

                    double finalhad = ent / j; // Declare and initialize finalhad in a broader scope
                    finalhad *= enr3;
                    // Your code that assigns a value to finalhad


                    // Now finalhad is accessible here
                    float zaribsabad = (float)(xx / finalhad);



                    long eslah = (long)(zaribsabad * chamm);
                    long pardaghtghblo = 0;
                    foreach (var item99 in bb)
                    {
                        pardaghtghblo += item99.Finalvaluesorat ?? 0;
                    }
                    long avalehsorat = eslah - pardaghtghblo;
                    sorat.basket7.cham = chamm;
                    sorat.basket7.chabli = pardaghtghblo;
                    sorat.basket7.zarib = zaribsabad;
                    sorat.basket7.aftereslahat = eslah;
                    sorat.basket7.aval = avalehsorat;




                    #endregion

                    long nahaeisorat = avalehsorat + kolpadash;
                    sorat.final = (long)nahaeisorat;


                }



            }
            else
            {
                // Handle if data retrieval fails
                // You can add logging or throw an exception
            }

            return View("~/Areas/Salaries/Views/Formula/view.cshtml", sorat);
        }
