        private string ConvertFormula3(string formula)
        {
            // ابتدا از عملگرهای منطقی مانند && و || محافظت می‌کنیم
            formula = formula.Replace("&&", "&AND&").Replace("||", "&OR&");

            // حذف & های اضافی
            formula = formula.Replace("&", "");

            // جایگزینی عملگرهای مناسب
            formula = formula.Replace("multiplication", "*")
                             .Replace("plus", "+")
                             .Replace("minus", "-")
                             .Replace("virgol", ",")
                             .Replace("Contrary", "!=")
                             .Replace("BiggerThan", ">")
                             .Replace("SmallerThan", "<").Replace("AND", "&&")
                                   .Replace("OR", "||")
                                                                      .Replace("Equal", "==")

                             .Replace("divide", "/");

            // برگرداندن عملگرهای منطقی
            formula = formula.Replace("&AND&", "&&").Replace("&OR&", "||");

            // تبدیل توان `a ^ b` به `Math.Pow(a, b)`
            formula = Regex.Replace(formula, @"(\d+)\s*\^\s*(\d+)", "Math.Pow($1, $2)");

            // پردازش `sigma`
            formula = ReplaceSigmaWithSum(formula);

            // تبدیل تمام `IF(شرط, مقدار1, مقدار2)` به `(شرط ? مقدار1 : مقدار2)`
            formula = ReplaceNestedIfs(formula);

            return formula;
        }
        public ActionResult CalculateFormula323(string Frml_Schema)
        {
            dynamic inputFormula = "";
            inputFormula = Frml_Schema;
            //var findd = db.tbFormula.Where(s => s.Frml_Priority == 1).FirstOrDefault();
            //if (findd != null)
            //{
            //    inputFormula = findd.Frml_Schema;
            //}

            if (string.IsNullOrWhiteSpace(inputFormula))
            {
                return Json(new { Error = "فرمول ورودی خالی است." }, JsonRequestBehavior.AllowGet);
            }

            string processedFormula = inputFormula;

            // **✅ حذف مقدار اولیه مانند `5_223&RU&` در ابتدای فرمول**
            string patternFirstNumber = @"^\d+_\d+(&RU&)?";
            processedFormula = Regex.Replace(processedFormula, patternFirstNumber, "");

            string patternFirstNumber1 = @"^\d+_\d+&";
            // **🔹 حذف مقدار اولیه عدد_عدد (مثلاً 2_187)**

            processedFormula = Regex.Replace(processedFormula, patternFirstNumber1, "");
            // **✅ جایگزینی مقدار عدد_عدد با مقدار صحیح از دیتابیس**

            // **✅ حذف `&` های اضافی و جایگزینی با عملگرهای مناسب**
            processedFormula = processedFormula.Replace("&plus&", "+")
                                               .Replace("&multiplication&", "*")
                                               .Replace("&minus&", "-")
                                               .Replace("&divide&", "/")
                                               .Replace("&SmallerThan&", "<")
                                               .Replace("&BiggerThan&", ">")
                                               .Replace("&Contrary&", "!=")
                                               .Replace("&virgol&", ",")
                                               .Replace("&AND&", "&&")
                                   .Replace("&OR&", "||")
                                               .Replace("&^&", "^");

            // **✅ جایگزینی `sigma(...)` با مقدار جمع‌شده از دیتابیس**
            processedFormula = ReplaceSigmaWithSum(processedFormula);
            // ✅ جایگزینی `Ave(...)` با مقدار میانگین

            // **✅ جایگزینی `Count(...)` با مقدار شمارش از دیتابیس**
            processedFormula = ReplaceCountWithValue(processedFormula);
            processedFormula = ReplaceNumericValuesFromDatabase(processedFormula);

            processedFormula = ReplaceAverageWithMean(processedFormula);

            // **✅ تبدیل `IF(شرط, مقدار1, مقدار2)` به `(شرط ? مقدار1 : مقدار2)`**
            processedFormula = ReplaceNestedIfs(processedFormula);

            string convertedFormula;
            try
            {
                convertedFormula = ConvertFormula3(processedFormula);
                Console.WriteLine("🔎 فرمول پردازش شده: " + convertedFormula);
            }
            catch (Exception ex)
            {
                return Json(new { Error = "فرمول نامعتبر است: " + ex.Message }, JsonRequestBehavior.AllowGet);
            }

            try
            {
                var options = ScriptOptions.Default
                    .WithReferences(typeof(Math).Assembly)
                    .WithImports("System");

                // تبدیل شیء به JSON و بازگرداندن آن
                string processedFormula1 = ConvertToLongFormat(convertedFormula);
                long finalResult = (long)Math.Round(
                   CSharpScript.EvaluateAsync<double>(processedFormula1, options).Result
               );
                //long finalResult = CSharpScript.EvaluateAsync<long>(processedFormula1, options).Result;

                return Content($"{{ \"ProcessedFormula\": \"{processedFormula1}\", \"Result\": {finalResult}, \"ConvertedFormula\": \"{convertedFormula}\" }}", "application/json");
            }
            catch (Exception ex)
            {
                // ساخت یک شیء JSON ایمن برای بازگرداندن خطا
                var errorResponse = new
                {
                    Error = "خطای پردازش فرمول",
                    Message = ex.Message,
                    ConvertedFormula = convertedFormula
                };

                // تبدیل شیء به JSON و بازگرداندن آن
                return Json(errorResponse, JsonRequestBehavior.AllowGet);
            }
        }

        public ActionResult CalculateFormula3()
        {
            dynamic inputFormula = "";
            var findd = db.tbFormula.Where(s => s.Frml_Priority == 1).FirstOrDefault();
            if (findd != null)
            {
                inputFormula = findd.Frml_Schema;
            }

            if (string.IsNullOrWhiteSpace(inputFormula))
            {
                return Json(new { Error = "فرمول ورودی خالی است." }, JsonRequestBehavior.AllowGet);
            }

            string processedFormula = inputFormula;

            // **✅ حذف مقدار اولیه مانند `5_223&RU&` در ابتدای فرمول**
            string patternFirstNumber = @"^\d+_\d+(&RU&)?";
            processedFormula = Regex.Replace(processedFormula, patternFirstNumber, "");

            string patternFirstNumber1 = @"^\d+_\d+&";
            // **🔹 حذف مقدار اولیه عدد_عدد (مثلاً 2_187)**

            processedFormula = Regex.Replace(processedFormula, patternFirstNumber1, "");
            // **✅ جایگزینی مقدار عدد_عدد با مقدار صحیح از دیتابیس**

            // **✅ حذف `&` های اضافی و جایگزینی با عملگرهای مناسب**
            processedFormula = processedFormula.Replace("&plus&", "+")
                                               .Replace("&multiplication&", "*")
                                               .Replace("&minus&", "-")
                                               .Replace("&divide&", "/")
                                               .Replace("&SmallerThan&", "<")
                                               .Replace("&BiggerThan&", ">")
                                               .Replace("&Contrary&", "!=")
                                               .Replace("&virgol&", ",")
                                               .Replace("&AND&", "&&")
                                   .Replace("&OR&", "||")
                                   .Replace("&Equal&", "==")
                                               .Replace("&^&", "^");

            // **✅ جایگزینی `sigma(...)` با مقدار جمع‌شده از دیتابیس**
            processedFormula = ReplaceSigmaWithSum(processedFormula);
            // ✅ جایگزینی `Ave(...)` با مقدار میانگین

            // **✅ جایگزینی `Count(...)` با مقدار شمارش از دیتابیس**
            processedFormula = ReplaceCountWithValue(processedFormula);
            processedFormula = ReplaceNumericValuesFromDatabase(processedFormula);

            processedFormula = ReplaceAverageWithMean(processedFormula);

            // **✅ تبدیل `IF(شرط, مقدار1, مقدار2)` به `(شرط ? مقدار1 : مقدار2)`**
            processedFormula = ReplaceNestedIfs(processedFormula);

            string convertedFormula;
            try
            {
                convertedFormula = ConvertFormula3(processedFormula);
                Console.WriteLine("🔎 فرمول پردازش شده: " + convertedFormula);
            }
            catch (Exception ex)
            {
                return Json(new { Error = "فرمول نامعتبر است: " + ex.Message }, JsonRequestBehavior.AllowGet);
            }
            try
            {
                var options = ScriptOptions.Default
                    .WithReferences(typeof(Math).Assembly)
                    .WithImports("System");

                // تبدیل فرمول به long
                string processedFormula1 = ConvertToLongFormat(convertedFormula);

                long finalResult = (long)Math.Round(
                    CSharpScript.EvaluateAsync<double>(processedFormula1, options).Result
                );
                return Content($"{{ \"ProcessedFormula\": \"{processedFormula1}\", \"Result\": {finalResult}, \"ConvertedFormula\": \"{convertedFormula}\" }}", "application/json");
            }
            catch (Exception ex)
            {
                var errorResponse = new
                {
                    Error = "خطای پردازش فرمول",
                    Message = ex.Message,
                    ConvertedFormula = convertedFormula
                };
                return Json(errorResponse, JsonRequestBehavior.AllowGet);
            }

        }
        public static string ConvertToLongFormat(string formula)
        {
            // فقط اعداد صحیح (بدون اعشار یا ممیز) رو به L تبدیل کن
            return Regex.Replace(formula, @"(?<![\d.])\d+(?![\.\d])", m => m.Value + "L");
        }
        public static string ReplaceAverageWithMean(string formula)
        {
            try
            {
                // الگوی Regex برای پیدا کردن `&Ave&(...)`
                string pattern = @"Ave&\(&([\d,]+)&\)";
                MatchCollection matches = Regex.Matches(formula, pattern);

                foreach (Match match in matches)
                {
                    string valuesRaw = match.Groups[1].Value;  // دریافت مقدار داخل `Ave(...)`
                    string[] values = valuesRaw.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

                    List<double> numericValues = values.Select(double.Parse).ToList(); // تبدیل رشته به عدد

                    // محاسبه میانگین
                    double averageValue = numericValues.Count > 0 ? numericValues.Average() : 0;

                    // جایگزینی مقدار `&Ave&(...)` در فرمول
                    formula = formula.Replace(match.Value, averageValue.ToString());
                }

                return formula;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"❌ خطا در پردازش Ave: {ex.Message}");
                return formula; // در صورت خطا، مقدار اصلی بازگردانی شود
            }
        }

