        public static DateTime ConvertShamsiYearToYear(int _shamsiYear, int _shamsiMonth)
        {
            PersianCalendar pc = new PersianCalendar();

            return new DateTime(_shamsiYear, _shamsiMonth, 29, pc);
        }
        public static long ConvertBase9ToBase10(string base9String)
        {
            long result = 0;
            int power = 0;

            // معکوس کردن رشته برای پردازش از چپ به راست
            foreach (char digitChar in base9String.Reverse())
            {
                int digit = digitChar - '0'; // تبدیل کاراکتر به عدد
                result += digit * (long)Math.Pow(9, power);
                power++;
            }

            return result;
        }
        private string ReplaceCountWithValue(string formula)
        {
            string pattern = @"Count\s*\(\s*(\d+)\s*/\s*(\d+)\s*/\s*(\d+)\s*,\s*(\d+)\s*/\s*(\d+)\s*/\s*(\d+)\s*,\s*(\d+)\s*_\s*(\d+)\s*\)";
            MatchCollection matches = Regex.Matches(formula, pattern);

            foreach (Match match in matches)
            {
                try
                {
                    int day1 = int.Parse(match.Groups[1].Value);
                    int month1 = int.Parse(match.Groups[2].Value);
                    int year1 = int.Parse(match.Groups[3].Value);

                    int day2 = int.Parse(match.Groups[4].Value);
                    int month2 = int.Parse(match.Groups[5].Value);
                    int year2 = int.Parse(match.Groups[6].Value);

                    string fkMoalefeRaw = match.Groups[7].Value + "_" + match.Groups[8].Value;

                    // ✅ استخراج عدد دوم از مقدار `9_1025`
                    string patternExtractSecondNumber = @"\d+_(\d+)";
                    Match extractMatch = Regex.Match(fkMoalefeRaw, patternExtractSecondNumber);

                    int fkMoalefe = extractMatch.Success ? int.Parse(extractMatch.Groups[1].Value) : 0;
                    int countValue = db.tbMoalefeValueFish
                        .Where(s => s.FK_Moalefe == fkMoalefe && s.FK_User == 801 &&
                                    ((s.mlfvlfsh_Year > year1 || (s.mlfvlfsh_Year == year1 && s.mlfvlfsh_Month >= month1)) &&
                                     (s.mlfvlfsh_Year < year2 || (s.mlfvlfsh_Year == year2 && s.mlfvlfsh_Month <= month2))))
                        .Count();

                    formula = formula.Replace(match.Value, countValue.ToString());
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"❌ خطا در پردازش Count: {ex.Message}{formula}");
                }
            }
            return formula;
        }

        private string ReplaceSigmaWithSum(string formula)
        {
            string pattern = @"sigma\s*\(\s*(\d+)\s*/\s*(\d+)\s*/\s*(\d+)\s*,\s*(\d+)\s*/\s*(\d+)\s*/\s*(\d+)\s*,\s*(\d+)\s*_\s*(\d+)\s*\)";
            MatchCollection matches = Regex.Matches(formula, pattern);

            foreach (Match match in matches)
            {
                try
                {
                    int day1 = int.Parse(match.Groups[1].Value);
                    int month1 = int.Parse(match.Groups[2].Value);
                    int year1 = int.Parse(match.Groups[3].Value);

                    int day2 = int.Parse(match.Groups[4].Value);
                    int month2 = int.Parse(match.Groups[5].Value);
                    int year2 = int.Parse(match.Groups[6].Value);

                    // ✅ دریافت مقدار کامل `9_1025`
                    string fkMoalefeRaw = match.Groups[7].Value + "_" + match.Groups[8].Value;

                    // ✅ استخراج عدد دوم از مقدار `9_1025`
                    string patternExtractSecondNumber = @"\d+_(\d+)";
                    Match extractMatch = Regex.Match(fkMoalefeRaw, patternExtractSecondNumber);

                    int fkMoalefe = extractMatch.Success ? int.Parse(extractMatch.Groups[1].Value) : 0;

                    Console.WriteLine($"✅ fkMoalefe مقدار صحیح دارد: {fkMoalefe}");

                    // دریافت مقدار جمع از دیتابیس
                    long sumValue = db.tbMoalefeValueFish
                                    .Where(s => s.FK_Moalefe == fkMoalefe && s.FK_User == 801 &&
                                                ((s.mlfvlfsh_Year > year1 || (s.mlfvlfsh_Year == year1 && s.mlfvlfsh_Month >= month1)) &&
                                                 (s.mlfvlfsh_Year < year2 || (s.mlfvlfsh_Year == year2 && s.mlfvlfsh_Month <= month2))))
                                    .Select(t => (long?)t.mlfvlfsh_Value)
                                    .Sum() ?? 0;

                    // جایگزینی مقدار `sigma(...)` در فرمول
                    formula = formula.Replace(match.Value, sumValue.ToString());
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"❌ خطا در پردازش sigma: {ex.Message}{formula}");
                }
            }
            return formula;
        }
        private string ReplaceNestedIfs(string formula)
        {
            while (formula.Contains("IF(") || formula.Contains("IF&("))
            {
                // تبدیل `IF&(` به `IF(` برای استانداردسازی
                formula = formula.Replace("IF&(", "IF(");

                // حذف `&` اضافی بعد از `IF(` 
                //formula = Regex.Replace(formula, @"IF\(\s*&", "IF(");
                //formula = formula.Replace("&", "");
                // حذف `&` اضافی بعد از `IF(` 
                formula = Regex.Replace(formula, @"IF\(\s*&", "IF(");

                // **تغییر به گونه‌ای که & های اضافی حذف شوند، مگر در عملگرهای && و ||**
                // جایگزینی & ها که در واقع یک عملگر منطقی نباشند
                formula = Regex.Replace(formula, @"(?<!&)(?<=\S)&(?=\S)(?!&)", "");
                // **پیدا کردن داخلی‌ترین `IF(...)` و جایگزینی آن**
                int lastIfIndex = formula.LastIndexOf("IF(");
                if (lastIfIndex == -1) break;

                int openBrackets = 1;
                int i = lastIfIndex + 3; // بعد از `IF(` حرکت کنیم

                while (i < formula.Length && openBrackets > 0)
                {
                    if (formula[i] == '(') openBrackets++;
                    if (formula[i] == ')') openBrackets--;
                    i++;
                }

                if (openBrackets > 0) break; // پرانتز‌بندی نادرست

                string ifExpression = formula.Substring(lastIfIndex, i - lastIfIndex);

                // جدا کردن شرط، مقدار true و مقدار false
                string innerContent = ifExpression.Substring(3, ifExpression.Length - 4); // حذف `IF(` و `)`
                string[] parts = innerContent.Split(',');

                if (parts.Length != 3) break; // ساختار نامعتبر

                string condition = parts[0].Trim();
                string truePart = parts[1].Trim();
                string falsePart = parts[2].Trim();
                string replacement = $"(({condition}) ? {truePart} : {falsePart})";

                //string replacement = $"({condition} ? {truePart} : {falsePart})";

                // جایگزینی اولین `IF(...)` پیدا شده
                formula = formula.Replace(ifExpression, replacement);
            }

            return formula;
        }



        public ActionResult ConvertFormula3ds1()
        {
            double cpunt1837 = 0;
            double cpunt1 = 0;
            double cpunt1118372 = 0;
            double cpunt111 = 0;

            // محاسبه مقدار cpunt و cpunt11 برای کاربر 860
            for (var it = 3; it <= 9; it++)
