                    .FirstOrDefault(s => s.FK_Moalefe == 1964 && s.FK_User == 860 && s.mlfvlfsh_Month == it && s.mlfvlfsh_Year == 1403);

                if (find2 != null)
                {
                    cpunt1837 += find2.mlfvlfsh_Value ?? 0;
                }
