                var find = db.tbMoalefeValueFish
                    .FirstOrDefault(s => s.FK_Moalefe == 1960 && s.FK_User == 860 && s.mlfvlfsh_Month == it && s.mlfvlfsh_Year == 1403);
                var find2 = db.tbMoalefeValueFish
                    .FirstOrDefault(s => s.FK_Moalefe == 1964 && s.FK_User == 860 && s.mlfvlfsh_Month == it && s.mlfvlfsh_Year == 1403);

                if (find2 != null)
                {
                    cpunt1118372 += find2.mlfvlfsh_Value ?? 0;
                }
                if (find != null)
                {
                    cpunt1118372 += find.mlfvlfsh_Value ?? 0;
                }
            }

            // محاسبه مقدار cpunt1 و cpunt111 برای کاربر 974
            for (var it = 10; it <= 12; it++)
            {
                var find = db.tbMoalefeValueFish
                    .FirstOrDefault(s => s.FK_Moalefe == 1960 && s.FK_User == 974 && s.mlfvlfsh_Month == it && s.mlfvlfsh_Year == 1403);
                var find2 = db.tbMoalefeValueFish
                    .FirstOrDefault(s => s.FK_Moalefe == 1964 && s.FK_User == 974 && s.mlfvlfsh_Month == it && s.mlfvlfsh_Year == 1403);

                if (find != null)
                {
                    cpunt111 += find.mlfvlfsh_Value ?? 0;
                }
                if (find2 != null)
                {
                    cpunt111 += find2.mlfvlfsh_Value ?? 0;
                }
            }

            // مقداردهی به cpunt11 و cpunt111 (در صورتی که مقدار خاصی برایشان نیاز باشد)
            // مثال: دو برابر مقدار cpunt1

