                    dataRow.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    { DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String, CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(row.Nametable ?? "") });
                    dataRow.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    { DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String, CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(row.FK_dbergharel4_5?.ToString() ?? "") });
                    dataRow.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
