        public ActionResult EXCEL_erja_omomi_byJob(long jobId = 1)
        {
            var stream = new MemoryStream();

            using (DocumentFormat.OpenXml.Packaging.SpreadsheetDocument document =
                DocumentFormat.OpenXml.Packaging.SpreadsheetDocument.Create(stream, DocumentFormat.OpenXml.SpreadsheetDocumentType.Workbook, true))
            {
                // ایجاد Workbook
                var workbookPart = document.AddWorkbookPart();
                workbookPart.Workbook = new DocumentFormat.OpenXml.Spreadsheet.Workbook();
                var sheets = workbookPart.Workbook.AppendChild(new DocumentFormat.OpenXml.Spreadsheet.Sheets());

                //----------------------------------------------------------
                // 📘 Sheet1 : اطلاعات عمومی و ستون‌های دینامیک erja_omomi
                //----------------------------------------------------------
                var sheet1Part = workbookPart.AddNewPart<DocumentFormat.OpenXml.Packaging.WorksheetPart>();
                sheet1Part.Worksheet = new DocumentFormat.OpenXml.Spreadsheet.Worksheet();
                var sheet1Data = sheet1Part.Worksheet.AppendChild(new DocumentFormat.OpenXml.Spreadsheet.SheetData());

                // دریافت داده‌ها از erja_omomi
                var erjaData = db.erja_omomi
                    .Where(x => x.FK_job == jobId && x.vaziat == 1)
                    .Select(x => new { x.ID, x.title })
                    .ToList();

                //----------------------------------------------------------
                // ردیف اول
                //----------------------------------------------------------
                var row1 = new DocumentFormat.OpenXml.Spreadsheet.Row();

                // سه ستون ثابت
                string[] fixedHeaders = { "نام و نام خانوادگی", "کد کاربر", "کار درخواستی" };
                foreach (var h in fixedHeaders)
                {
                    row1.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(h)
                    });
                }

                // ستون‌های داینامیک از erja_omomi (ID)
                foreach (var item in erjaData)
                {
                    row1.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.Number,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(item.ID.ToString())
                    });
                }
                sheet1Data.Append(row1);

                //----------------------------------------------------------
                // ردیف دوم (سه ستون اول خالی + titleها)
                //----------------------------------------------------------
                var row2 = new DocumentFormat.OpenXml.Spreadsheet.Row();

                // سه ستون اول خالی
                for (int i = 0; i < 3; i++)
                {
                    row2.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue("")
                    });
                }

                // عنوان‌ها از erja_omomi
                foreach (var item in erjaData)
                {
                    row2.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(item.title ?? "")
                    });
                }
                sheet1Data.Append(row2);

                // چند ردیف خالی بعدی (اختیاری)
                for (int i = 0; i < 3; i++)
                {
                    sheet1Data.Append(new DocumentFormat.OpenXml.Spreadsheet.Row());
                }

                sheets.Append(new DocumentFormat.OpenXml.Spreadsheet.Sheet()
                {
                    Id = workbookPart.GetIdOfPart(sheet1Part),
                    SheetId = 1,
                    Name = "erja_omomi"
                });

                //----------------------------------------------------------
                // 📗 Sheet2 : اطلاعات کاربران
                //----------------------------------------------------------
                var sheet2Part = workbookPart.AddNewPart<DocumentFormat.OpenXml.Packaging.WorksheetPart>();
                sheet2Part.Worksheet = new DocumentFormat.OpenXml.Spreadsheet.Worksheet();
                var sheet2Data = sheet2Part.Worksheet.AppendChild(new DocumentFormat.OpenXml.Spreadsheet.SheetData());

                // Header Sheet2
                var headerRow2 = new DocumentFormat.OpenXml.Spreadsheet.Row();
                string[] headers2 = { "نام", "نام خانوادگی","کد پرسنلی","usr_ID" };
                foreach (var h in headers2)
                {
                    headerRow2.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(h)
                    });
                }
                sheet2Data.Append(headerRow2);

                // داده‌های کاربران
                var users = db.tbUsers
                    .Select(u => new { u.usr_Name, u.usr_Family, u.usr_Personal_ID, u.usr_ID })
                    .ToList();

                foreach (var user in users)
                {
                    var row = new DocumentFormat.OpenXml.Spreadsheet.Row();
                    row.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(user.usr_Name ?? "")
                    });
                    row.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(user.usr_Family ?? "")
                    }); row.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.String,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(user.usr_Personal_ID.ToString() ?? "")
                    });
                    row.Append(new DocumentFormat.OpenXml.Spreadsheet.Cell()
                    {
                        DataType = DocumentFormat.OpenXml.Spreadsheet.CellValues.Number,
                        CellValue = new DocumentFormat.OpenXml.Spreadsheet.CellValue(user.usr_ID.ToString())
                    });
                    sheet2Data.Append(row);
                }

                sheets.Append(new DocumentFormat.OpenXml.Spreadsheet.Sheet()
                {
                    Id = workbookPart.GetIdOfPart(sheet2Part),
                    SheetId = 2,
                    Name = "Users"
                });

                workbookPart.Workbook.Save();
            }

            stream.Position = 0;
            string fileName = $"erja_omomi_job_{jobId}.xlsx";
            return File(stream, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", fileName);
        }


