            IQueryable<Create_linkmamorjob_4> baseQuery = db.Create_linkmamorjob_4
        .Where(s => s.month == month
                 && s.Create_linkrelation2job_3.Create_linkjob_2.FK_job == job
                 && s.year == year);

            List<Create_linkmamorjob_4> detailuniccc;

            if (job == 1)
            {
                detailuniccc = baseQuery
                    .AsEnumerable() // از اینجا به بعد روی حافظه اجرا میشه، نه SQL
                    .GroupBy(s => s.FK_link)
                    .SelectMany(g =>
                    {
                        var lastTwo = g.OrderByDescending(x => x.ID).Take(2).ToList();

                        if (lastTwo.Count == 2 && lastTwo[0].FK_usr != lastTwo[1].FK_usr)
                        {
                            return lastTwo;
                        }

                        return new List<Create_linkmamorjob_4> { lastTwo.First() };
                    })
                    .ToList();
            }

            else
            {
                // برای هر FK_link یکی آخر
                detailuniccc = baseQuery
                    .GroupBy(s => s.FK_link)
                    .Select(g => g.OrderByDescending(x => x.ID).FirstOrDefault()) // یا x.ID
                    .ToList();
            }

            // گروه بندی detailها براساس unic

            // ساختن لیست tbUsers بر اساس findAdam
            List<tbUsers> tbUsers = new List<tbUsers>();
            var findAdam = db.tbAdamAdam.Where(s => s.Name == personal && s.Value == 1).ToList();
            foreach (var itt in findAdam)
            {
                var u = db.tbUsers.FirstOrDefault(s => s.usr_ID == itt.nam);
                if (u != null)
                    tbUsers.Add(u);
            }

            var stream = new MemoryStream();

            using (SpreadsheetDocument document = SpreadsheetDocument.Create(stream, SpreadsheetDocumentType.Workbook, true))
            {
                WorkbookPart workbookPart = document.AddWorkbookPart();
                workbookPart.Workbook = new OxWorkbook();
                OxSheets sheets = workbookPart.Workbook.AppendChild(new OxSheets());

                // --- Sheet: Jobs ---
                WorksheetPart wsJobsPart = workbookPart.AddNewPart<WorksheetPart>();
                using (OpenXmlWriter writer = OpenXmlWriter.Create(wsJobsPart))
                {
                    writer.WriteStartElement(new OxWorksheet());
                    writer.WriteStartElement(new OxSheetData());

                    // header
                    writer.WriteStartElement(new OxRow());
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("کد یکتا") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("نام شغل تعریف شده") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("کد پرسنلی") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("نام و نام خانوادگی") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("شهرستان") });

                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("عملیات") });

                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("زمان ثبت ") });

                    foreach (var rJob in realJobs)
                    {
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.Number, CellValue = new OxCellValue(rJob.nam.ToString()) });
                    }
                    writer.WriteEndElement(); // header row

                    // data rows
                    foreach (var group in detailuniccc)
                    {
                        string unic = group.unic ?? "";

                        string jobName = group.Create_linkrelation2job_3?.Create_linkjob_2?.Create_job_1?.name ?? "";

                        string fullname = group.tbUsers?.FullName ?? "";

                        int personalI3D = group.tbUsers?.usr_Personal_ID ?? 0;

                        string namecity = "";
                        if (group.tbUsers?.usr_City_Dutysystem != null)
                        {
                            var findcity = db.tbCities.FirstOrDefault(s => s.ID == group.tbUsers.usr_City_Dutysystem);
                            if (findcity != null)
                                namecity = findcity.Name ?? "";
                        }

                        string amal = group.valueamal ?? "";
                        string time = group.timesabtsahmsi ?? "";

                        writer.WriteStartElement(new OxRow());

                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(unic) });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(jobName) });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.Number, CellValue = new OxCellValue(personalI3D.ToString()) });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(fullname) });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(namecity) });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(amal) });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(time) });
                        foreach (var rJob in realJobs)
                        {
                            string vakue = "";
                            if (relationLookup.TryGetValue(group.unic, out var jobDict))
                            {
                                jobDict.TryGetValue(rJob.ID, out vakue);
                            }

                            writer.WriteElement(new OxCell()
                            {
                                DataType = OxCellValues.Number,
                                CellValue = new OxCellValue(vakue ?? "")
                            });
                        }

                        writer.WriteEndElement(); // data row
                    }


                    writer.WriteEndElement(); // OxSheetData
                    writer.WriteEndElement(); // OxWorksheet
                }

                OxSheet sheetJobs = new OxSheet()
                {
                    Id = workbookPart.GetIdOfPart(wsJobsPart),
                    SheetId = 1U,
                    Name = "Jobs"
                };
                sheets.Append(sheetJobs);

                // --- Sheet: Operations ---
                // --- Sheet: Operations ---
                WorksheetPart wsOpsPart = workbookPart.AddNewPart<WorksheetPart>();
                using (OpenXmlWriter writer = OpenXmlWriter.Create(wsOpsPart))
                {
                    writer.WriteStartElement(new OxWorksheet());
                    writer.WriteStartElement(new OxSheetData());

                    // header
                    writer.WriteStartElement(new OxRow());
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("عملیات") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("نام و نام خانوادگی") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("کد پرسنلی") });
                    writer.WriteEndElement(); // header row

                    // data rows (عملیات + کاربر در هر ردیف)
                    int maxCount = Math.Max(realJobs22.Count, tbUsers.Count);
                    for (int i = 0; i < maxCount; i++)
                    {
                        var r = (i < realJobs22.Count) ? realJobs22[i] : null;
                        var u = (i < tbUsers.Count) ? tbUsers[i] : null;

                        writer.WriteStartElement(new OxRow());

                        // عملیات
                        writer.WriteElement(new OxCell()
                        {
                            DataType = OxCellValues.String,
                            CellValue = new OxCellValue(r?.name ?? "")
                        });

                        // نام و نام خانوادگی
                        writer.WriteElement(new OxCell()
                        {
                            DataType = OxCellValues.String,
                            CellValue = new OxCellValue(u?.FullName ?? "")
                        });

                        // کد پرسنلی
                        writer.WriteElement(new OxCell()
                        {
                            DataType = OxCellValues.String,
                            CellValue = new OxCellValue(u?.usr_Personal_ID?.ToString() ?? "")
                        });

                        writer.WriteEndElement(); // data row
                    }

                    writer.WriteEndElement(); // OxSheetData
                    writer.WriteEndElement(); // OxWorksheet
                }

                OxSheet sheetOps = new OxSheet()
                {
                    Id = workbookPart.GetIdOfPart(wsOpsPart),
                    SheetId = 2U,
                    Name = "Operations"
                };
                sheets.Append(sheetOps);

                workbookPart.Workbook.Save();
            }

            stream.Position = 0;
            string fileName = $"moshtrak_{year}_{month}.xlsx";
            return File(stream, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", fileName);
        }

