        public ActionResult EXCEL_timearzyab_mostakrin22(int month = 0, int year = 0, long job = 0)
        {
            var stream = new MemoryStream();

            using (SpreadsheetDocument document = SpreadsheetDocument.Create(stream, SpreadsheetDocumentType.Workbook, true))
            {
                WorkbookPart workbookPart = document.AddWorkbookPart();
                workbookPart.Workbook = new OxWorkbook();
                OxSheets sheets = workbookPart.Workbook.AppendChild(new OxSheets());

                // ===== Sheet1 : Create_realjob2_2 =====
                var realJobs = db.Create_realjob2_2
                                 .Where(r => r.FK_Create_linkjob_2 == job)
                                 .AsNoTracking()
                                 .ToList();

                WorksheetPart wsRealJobPart = workbookPart.AddNewPart<WorksheetPart>();
                using (OpenXmlWriter writer = OpenXmlWriter.Create(wsRealJobPart))
                {
                    writer.WriteStartElement(new OxWorksheet());
                    writer.WriteStartElement(new OxSheetData());

                    // --- Row1: IDs ---
                    writer.WriteStartElement(new OxRow());
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("کد یکتا") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("شهرستان") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("کد شهرستان ") });

                    foreach (var item in realJobs)
                    {
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.Number, CellValue = new OxCellValue(item.ID.ToString()) });
                    }
                    writer.WriteEndElement(); // row

                    // --- Row2: Nams ---
                    writer.WriteStartElement(new OxRow());
                    writer.WriteElement(new OxCell()); // unic column skip
                    writer.WriteElement(new OxCell()); // city column skip
                    writer.WriteElement(new OxCell()); // city column skip

                    foreach (var item in realJobs)
                    {
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(item.nam ?? "") });
                    }
                    writer.WriteEndElement(); // row

                    writer.WriteEndElement(); // sheetData
                    writer.WriteEndElement(); // worksheet
                }

                OxSheet sheet1 = new OxSheet()
                {
                    Id = workbookPart.GetIdOfPart(wsRealJobPart),
                    SheetId = 1U,
                    Name = "RealJobs"
                };
                sheets.Append(sheet1);

                // ===== Sheet2 : tbpeymancities JOIN tbCities =====
                var peymanCities = db.tbpeymancities
                                     .GroupBy(p => p.FK_City)
                                     .Select(g => new
                                     {
                                         FK_City = g.Key,
                                         Count = g.Count()
                                     })
                                     .ToList();

                // join with tbCities
                var cityData = (from pc in peymanCities
                                join c in db.tbCities on pc.FK_City equals c.ID
                                select new
                                {
                                    CityId = pc.FK_City,
                                    CityName = c.Name,
                                    Count = pc.Count
                                }).ToList();

                WorksheetPart wsCitiesPart = workbookPart.AddNewPart<WorksheetPart>();
                using (OpenXmlWriter writer = OpenXmlWriter.Create(wsCitiesPart))
                {
                    writer.WriteStartElement(new OxWorksheet());
                    writer.WriteStartElement(new OxSheetData());

                    // header
                    writer.WriteStartElement(new OxRow());
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("کد شهر") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("نام شهر") });
                    writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue("تعداد رکورد") });
                    writer.WriteEndElement();

                    // data
                    foreach (var c in cityData)
                    {
                        writer.WriteStartElement(new OxRow());
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.Number, CellValue = new OxCellValue(c.CityId.ToString()) });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.String, CellValue = new OxCellValue(c.CityName ?? "") });
                        writer.WriteElement(new OxCell() { DataType = OxCellValues.Number, CellValue = new OxCellValue(c.Count.ToString()) });
                        writer.WriteEndElement();
                    }

                    writer.WriteEndElement(); // sheetData
                    writer.WriteEndElement(); // worksheet
                }

                OxSheet sheet2 = new OxSheet()
                {
                    Id = workbookPart.GetIdOfPart(wsCitiesPart),
                    SheetId = 2U,
                    Name = "Cities"
                };
                sheets.Append(sheet2);

                workbookPart.Workbook.Save();
            }

            stream.Position = 0;
            string fileName = $"moshtrak_{year}_{month}.xlsx";

            return File(stream, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", fileName);
        }





