        public ActionResult CalculateSoratFormula(List<int> Pyman_ID, int Month, int Year)
        {

            PersianCalendar pc = new PersianCalendar();


            //فعلا یک پیمان

            var Pyman_ID2 = Pyman_ID.First();


            var userdetail = db.tbSoratSalaryDetail.Where(p => p.FK_Pymn == Pyman_ID2 && p.Soratslrydtl_Year == Year && p.course == Month).FirstOrDefault();
            Dictionary<int, string> Detail = new Dictionary<int, string>();

            var myDatetime = ConvertDateTimeToShamsi.ConvertShamsiYearToYear(Year, Month);
            //var haveContract = db.tbUserContracts.Where(p => p.FK_UserID == UsrID && p.usc_EndTime >= myDatetime && p.usc_StartTime <= myDatetime).Any();
            var haveContract = db.tbPeymanContracts.Where(p => p.pec_ID == Pyman_ID2 && p.Inactive != true).Any();
            if (userdetail == null)//آگر اطلاعات جهت محاسبه فیش حقوقی کاربر پیدا نشد

            {
                Detail = new Dictionary<int, string>();
                Detail.Add(0, "اطلاعات مربوط به این کاربر وجود ندارد");
                UserSalaryDetailVM Mode2 = new UserSalaryDetailVM
                {
                    HaveProblem = true,
                    Detail = Detail
                };
                return PartialView("_ModalCalculateFormula", Mode2);
            }
            //اگر یکی از اطلاعات مربوط به فیش مشکل داشت
            else if (userdetail.Soratslrydtl_Consolidation == false || userdetail.Soratslrydtl_PerformanceSave == false || userdetail.Soratslrydtl_PerformanceAccept == false)
            {
                Detail = new Dictionary<int, string>();
                Detail.Add(1, haveContract.ToString());
                Detail.Add(2, userdetail.Soratslrydtl_Consolidation.ToString());
                Detail.Add(3, userdetail.Soratslrydtl_PerformanceSave.ToString());
                Detail.Add(4, userdetail.Soratslrydtl_PerformanceAccept.ToString());
                SoratSalaryDetailControllerVM Model = new SoratSalaryDetailControllerVM
                {
                    HaveProblem = true,
                    Detail = Detail
                };
                return PartialView("_ModalCalculateSoratFormula", Model);
            }
            //اگر همه چیز اوکی بود
            else
            {
                Detail = new Dictionary<int, string>();
                Detail.Add(1, haveContract.ToString());
                Detail.Add(2, userdetail.Soratslrydtl_Consolidation.ToString());
                Detail.Add(3, userdetail.Soratslrydtl_PerformanceSave.ToString());
                Detail.Add(4, userdetail.Soratslrydtl_PerformanceAccept.ToString());
                SoratSalaryDetailControllerVM Model = new SoratSalaryDetailControllerVM
                {
                    HaveProblem = false,
                    Detail = Detail
                };
                return PartialView("_ModalCalculateSoratFormula", Model);
            }




        }



