        [HttpPost]
        public async Task<ActionResult> SaveSharhSooratVaziat(
    long FK_pymn = 0,
    long numbersorat = 0,
    int month = 0,
    int year = 0,
    string sharh = "",
    int vaziat = 0)
        {
            if (FK_pymn == 0 || numbersorat == 0 || month == 0 || year == 0)
                return Content("ورودی نامعتبر است");

            // پیدا کردن رکورد موجود برای همان پیمان، شماره صورت وضعیت، سال و ماه
            var exist = db.dbsharh_soratvaziat.FirstOrDefault(x =>
                x.FK_pymn == FK_pymn &&
                x.numbersorat == numbersorat &&
                x.month == month &&
                x.year == year);

            if (exist != null)
            {
                // آپدیت
                exist.sharh = sharh;
                exist.vaziat = vaziat;
                // اگر دوست داری شماره صورت و ... هم قابل تغییر باشد:
                // exist.numbersorat = numbersorat;
                // exist.month = month;
                // exist.year = year;
            }
            else
            {
                // اینسرت
                var model = new dbsharh_soratvaziat
                {
                    FK_pymn = FK_pymn,
                    sharh = sharh,
                    numbersorat = numbersorat,
                    month = month,
                    year = year,
                    vaziat = vaziat
                };

                db.dbsharh_soratvaziat.Add(model);
            }

            await db.SaveChangesAsync();
            return Content("true");
        }

