        public async Task<ActionResult> deletefish(int Month = 0, int Year = 0, int id = 0)
        {
            var findsoratva = db.tbMoalefeValueFish.Where(s => s.tbUsers.usr_Personal_ID == id && s.mlfvlfsh_Month == Month && s.mlfvlfsh_Year == Year&&s.FK_EXCel ==null ).ToList();
            db.tbMoalefeValueFish.RemoveRange(findsoratva);
            await db.SaveChangesAsync();
            string inputDate = "1" + "/" + Month + "/" + Year;
            DateTime persianDate = PersianDateToDateTime(inputDate);
            var find = db.FinancialDocuments.Where(p => p.tbUsers.usr_Personal_ID == id && p.DataDocument == persianDate).ToList();
            db.FinancialDocuments.RemoveRange(find);
            await db.SaveChangesAsync();
            return Content("true");



        }
        public static DateTime PersianDateToDateTime(string persianDate)
        {
            PersianCalendar persianCalendar = new PersianCalendar();
            string[] parts = persianDate.Split('/');
            int year = int.Parse(parts[2]);
            int month = int.Parse(parts[1]);
            int day = int.Parse(parts[0]);
            return persianCalendar.ToDateTime(year, month, day, 0, 0, 0, 0);
        }
