public int TeadaroozMonth(int Month, int year)
        {
            PersianCalendar pc = new PersianCalendar();

            if (Month < 7)
            {
                return 31;
            }
            else if (Month < 12)
            {

                return 30;
            }
            else
            {
                if (pc.IsLeapYear(year))
                {
                    return 30;
                }
                else
                {
                    return 29;
                }
            }
        }
        [HttpPost]
        public ActionResult tbtatialtmoadelcreat(List<tbtatialtmoadel> tbtatialtmoadel)
        {
            foreach (var item in tbtatialtmoadel)
            {
                var existing = db.tbtatialtmoadel
                                 .FirstOrDefault(x => x.month == item.month && x.year == item.year);

                if (existing != null)
                {
                    // Update existing record
                    existing.rozmonth = item.rozmonth;
                    existing.friday = item.friday;
                    existing.notfriday = item.notfriday;
                    existing.ghas = item.ghas;
                    existing.khales = item.khales;
                }
                else
                {
                    // Add new record
                    db.tbtatialtmoadel.Add(item);
                }
            }

            db.SaveChanges();
            return Json(new { success = true });
        }


        

