        public double CalculateTaxTajamoe(double mashmoolmaliyat, int year, int Month, int UserID, int eydivapadash)
        {

            #region بدست آوردن مشمول مالیات ها از ماه شروع فرد تا به حال

            float result = 0;
            var myDatetime = ConvertDateTimeToShamsi.ConvertShamsiYearToYear(year, Month);
            var MoalefeID = db.tbContractMoalefeDastmozdi.FirstOrDefault(p => p.md_Title == "جمع کل مشمول مالیات (ریال)").md_ID;

            var havecontract = db.tbUserContracts.FirstOrDefault(p => p.FK_UserID == UserID && p.usc_StartTime <= myDatetime && p.usc_EndTime >= myDatetime);

            if (havecontract != null)
            {
                int startMonth = havecontract.ShamsiStartTime_month;
                for (int i = startMonth; i < Month; i++)
                {
                    var x111 = db.tbMoalefeValueFish.FirstOrDefault(p => p.FK_User == UserID && p.mlfvlfsh_Year == year && p.mlfvlfsh_Month == i && p.FK_Moalefe == MoalefeID && p.mlfvlfsh_Submit == true);
                    if (x111 != null)
                    {
                        mashmoolmaliyat += (double)x111.mlfvlfsh_Value;

                    }
                }
                #endregion


                #region محاسبه مالیات تجمعی بر اساس مشمول مالیات فرد تا به الان

                //double teadadmah = havecontract.FirstMonthFish+1??0;// Month - startMonth + 1;//بدست آوردن تعداد ماه تا به الان
                var MoalefeID22 = db.tbContractMoalefeDastmozdi.FirstOrDefault(p => p.md_Title == "خالص قابل دریافت (ریال)").md_ID;
                var t = db.tbMoalefeValueFish.Where(p => p.mlfvlfsh_Year == year && p.FK_User == UserID && p.mlfvlfsh_Submit == true && p.FK_Moalefe == MoalefeID22 && p.mlfvlfsh_Value > 0).ToList();
                double teadadmah = t.Count + 1;
                if (Month == 12)//اگر ماه دوازده بود عیدی و پاداش اضافه میشه و همچنین یدونه معافیت مالیاتی بهش اضافه میشه یعنی تعداد ماه یدونه اضافه میشه
                {
                    mashmoolmaliyat += eydivapadash;
                    teadadmah += (teadadmah / 12);
                }


                var liststeptaxes = stepTaxRepository.List().Where(p => p.year == year).OrderBy(p => p.number).ToList();
                float min = 0;
                float max = 0;
                int step = 0;
                int ii = 0;
                double x = 0;

                foreach (var item in liststeptaxes)
                {
                    if (Month == 12)
                    {
                        if (ii == 1)
                        {
                            min = (float)(item.Fromamount * (teadadmah));
                            max = (float)(item.Toamount * (teadadmah - 1));
                            max += (float)x;
                            //min += (float)x;
                            if (mashmoolmaliyat >= min && mashmoolmaliyat <= max)
                            {
                                step = (int)item.number;
                                break;
                            }
                            ii = 2;
                        }
                        else if (ii != 1 && ii != 0)
                        {
                            min = (float)(item.Fromamount * (teadadmah - 1));
                            max = (float)(item.Toamount * (teadadmah - 1));
                            max += (float)x;
                            min += (float)x;
                            if (mashmoolmaliyat >= min && mashmoolmaliyat <= max)
                            {
                                step = (int)item.number;
                                break;
                            }
                        }

                        else
                        {
                            min = (float)(item.Fromamount * teadadmah);
                            max = (float)(item.Toamount * teadadmah);
                            x = (double)item.Toamount;
                            if (mashmoolmaliyat >= min && mashmoolmaliyat <= max)
                            {
                                step = (int)item.number;
                                break;
                            }
                            ii = 1;
                        }
                    }


                    else
                    {
                        min = (float)(item.Fromamount * teadadmah);
                        max = (float)(item.Toamount * teadadmah);
                        if (mashmoolmaliyat >= min && mashmoolmaliyat <= max)
                        {
                            step = (int)item.number;
                            break;
                        }

                    }


                }
                double x11 = 0;
                ii = 0;

                for (int i = 1; i < step; i++)
                {

                    if (Month == 12)
                    {
                        if (ii == 1)
                        {
                            ii = 2;
                            result = (float)((((liststeptaxes[i - 1].Toamount) * (teadadmah - 1)) + x11 - (liststeptaxes[i - 1].Fromamount * teadadmah)) * ((liststeptaxes[i - 1].Percent_amount) / 100)) + result;
                        }
                        else if (ii != 1 && ii != 0)
                        {

                            result = (float)(((((liststeptaxes[i - 1].Toamount) * (teadadmah - 1)) + x11) - ((liststeptaxes[i - 1].Fromamount * (teadadmah - 1)) + x11)) * ((liststeptaxes[i - 1].Percent_amount) / 100)) + result;
                        }
                        else
                        {
                            result = (float)((((liststeptaxes[i - 1].Toamount) * teadadmah) - (liststeptaxes[i - 1].Fromamount * teadadmah)) * ((liststeptaxes[i - 1].Percent_amount) / 100)) + result;
                            ii = 1;
                            x11 = (double)(((liststeptaxes[i - 1].Toamount)));
                        }

                    }
                    else
                    {
                        result = (float)((((liststeptaxes[i - 1].Toamount) * teadadmah) - (liststeptaxes[i - 1].Fromamount * teadadmah)) * ((liststeptaxes[i - 1].Percent_amount) / 100)) + result;

                    }


                }
                if (Month == 12)
                {
                    result = (float)((mashmoolmaliyat - ((liststeptaxes[step - 1].Fromamount * (teadadmah - 1)) + x11)) * ((liststeptaxes[step - 1].Percent_amount) / 100)) + result;

                }

                else
                {
                    result = (float)((mashmoolmaliyat - (liststeptaxes[step - 1].Fromamount * teadadmah)) * ((liststeptaxes[step - 1].Percent_amount) / 100)) + result;

                }
                #endregion

                #region کم کردن میزان مالیاتی که تا الان داده از مالیاتی که این ماه براش حساب کردیم

                var MoalefeIDmaliyat = db.tbContractMoalefeDastmozdi.FirstOrDefault(p => p.md_Title == "مالیات سهم کارمند (ریال)").md_ID;
                int LastMonth = 1;
                if (Month != 1)
                {
                    LastMonth = Month - 1;
                }
                int jammaliyatqabl = 0;

                for (int i = LastMonth; i >= 1; i--)
                {
                    var moalefefish = db.tbMoalefeValueFish.FirstOrDefault(p => p.FK_User == UserID && p.mlfvlfsh_Year == year && p.mlfvlfsh_Month == i && p.FK_Moalefe == MoalefeIDmaliyat && p.mlfvlfsh_Submit == true);
                    if (moalefefish != null)
                    {
                        jammaliyatqabl += System.Convert.ToInt32(moalefefish.mlfvlfsh_Value);
                    }
                }
                var cit = db.tbUsers.Where(p => p.usr_ID == UserID).FirstOrDefault();
                if (cit.usr_City_Dutysystem != null)
                {
                    var city = db.tbCities.Where(p => p.ID == cit.usr_City_Dutysystem).FirstOrDefault();
                    if (city.Zaribmalyat != null)
                    {
                        result = (float)city.Zaribmalyat / 100 * result;

                    }
                }

                if (result - jammaliyatqabl < 0)
                {
                    result = 0;
                }
                else
                {
                    result = result - jammaliyatqabl;
                }



                #endregion

            }

            return result;
        }

        public async Task<ActionResult> mohasebehbemh(int month = 0, int year = 0)
        {
            // 1. گرفتن همه رکوردهای مشمول مالیات 1960 یکجا
            var mashmolUsers = await db.tbMoalefeValueFish
                .Where(s => s.FK_Moalefe == 1960 &&
                            s.mlfvlfsh_Month == month &&
                            s.mlfvlfsh_Year == year &&
                            s.mlfvlfsh_Value > 0 &&
                            s.FK_EXCel == null)
                .ToListAsync();

            var userIds = mashmolUsers.Select(x => x.FK_User).ToList();

            // 2. گرفتن همه رکوردهای 1986 برای همین کاربران و ماه/سال
            var mashmool1986 = await db.tbMoalefeValueFish
                .Where(s => s.FK_Moalefe == 1986 &&
                            s.mlfvlfsh_Month == month &&
                            s.mlfvlfsh_Year == year &&
                            userIds.Contains(s.FK_User))
                .ToListAsync();

            var mashmoolDict1986 = mashmool1986.ToDictionary(x => x.FK_User, x => x);

            // 3. گرفتن رکوردهای مالیات قبلی 1987
            var previousTaxes = await db.tbMoalefeValueFish
                .Where(s => s.FK_Moalefe == 1987 &&
                            s.mlfvlfsh_Year == year &&
                            s.mlfvlfsh_Month <= month)
                .ToListAsync();

            var previousTaxesDict = previousTaxes
                .GroupBy(x => x.FK_User)
                .ToDictionary(g => g.Key, g => g.ToList());

            List<tbMoalefeValueFish> recordsToAddOrUpdate = new List<tbMoalefeValueFish>();

            foreach (var userId in userIds)
            {
                // مقدار اصلی برای محاسبه مالیات از 1986
                if (!mashmoolDict1986.TryGetValue(userId, out var findmashmol))
                    continue; // اگر رکورد 1986 موجود نبود، نادیده بگیر

                double value = CalculateTaxTajamoe((double)findmashmol.mlfvlfsh_Value, year, month, (int)userId, 0);

                // بررسی رکورد قبلی مالیات 1987
                var existing = previousTaxesDict.ContainsKey(userId)
                    ? previousTaxesDict[userId].FirstOrDefault(x => x.mlfvlfsh_Month == month)
                    : null;

                if (existing != null)
                {
                    existing.mlfvlfsh_Value = value;
                    existing.Datatmie = DateTime.Now;
                    recordsToAddOrUpdate.Add(existing);
                }
                else
                {
                    recordsToAddOrUpdate.Add(new tbMoalefeValueFish
                    {
                        FK_Moalefe = 1987,
                        FK_User = userId,
                        mlfvlfsh_Value = value,
                        mlfvlfsh_Year = year,
                        mlfvlfsh_Month = month,
                        mlfvlfsh_Submit = null,
                        Finalaccept = null,
                        FK_EXCel = null,
                        submit = null,
                        Datatmie = DateTime.Now
                    });
                }
            }

            // ذخیره‌سازی همه تغییرات یکجا
            db.tbMoalefeValueFish.AddRange(recordsToAddOrUpdate);
            await db.SaveChangesAsync();

            return Content("true");
        }
        public ActionResult GenerateUserFishPdf(int userId, int month, int year)
        {
            var result = ShowFish(userId, month, year) as PartialViewResult;
            if (result != null)
            {
                var model = result.Model as ManualFishDetail;
                if (model != null)
                {
                    var pdf = GeneratePdf(model);
                    var fileName = $"Fish_{userId}_{month}_{year}.pdf";
                    var filePath = System.IO.Path.Combine(Directory.GetCurrentDirectory(), "wwwroot", "pdfs", fileName);
                    System.IO.File.WriteAllBytes(filePath, pdf);
                    return Content($"PDF for user {userId} created successfully.");
                }
            }
            return Content($"Failed to create PDF for user {userId}.");
        }
        private readonly IConverter _converter;

        public FormulaController(IConverter converter)
        {
            _converter = converter;
        }
        private byte[] GeneratePdf(ManualFishDetail model)
        {
            var htmlContent = RenderViewToString(ControllerContext, "FishView2", model);
            var doc = new HtmlToPdfDocument()
            {
                GlobalSettings = {
            ColorMode = ColorMode.Color,
            Orientation = DinkToPdf.Orientation.Portrait, // استفاده از DinkToPdf.Orientation برای حل ابهام
            PaperSize = PaperKind.A4
        },
                Objects = {
            new ObjectSettings() {
                PagesCount = true,
                HtmlContent = htmlContent,
                WebSettings = { DefaultEncoding = "utf-8" }
            }
        }
            };

            return _converter.Convert(doc);
        }
        private string RenderViewToString(ControllerContext context, string viewName, object model)
        {
            ViewData.Model = model;
            using (var sw = new StringWriter())
            {
                var viewResult = ViewEngines.Engines.FindPartialView(context, viewName);
                var viewContext = new ViewContext(context, viewResult.View, ViewData, TempData, sw);
                viewResult.View.Render(viewContext, sw);
                viewResult.ViewEngine.ReleaseView(context, viewResult.View);
                return sw.GetStringBuilder().ToString();
            }
        }
        public ActionResult GenerateAllFishPdfs(int month, int year)
        {
            var users = db.tbUsers.ToList();

            foreach (var user in users)
            {
                GenerateUserFishPdf(user.usr_ID, month, year);
            }

            return Content("All PDFs generated successfully.");
        }
