        public ActionResult GenerateScript(ControlVersions version)
        {
            try
            {
                // ترد برای اجرای اسکریپت در بک‌اند
                Thread thread = new Thread(() => GenerateScripts(db, version));
                thread.Start();

                ViewBag.Message = "فرایند تولید اسکریپت آغاز شد.";
            }
            catch (Exception ex)
            {
                ViewBag.Message = "خطا در تولید اسکریپت: " + ex.Message;
            }

            return View("Index");
        }
