        // متد برای تولید اسکریپت
        private void GenerateScripts(SaabEntities db, ControlVersions version)
        {
            try
            {
                string connectionString = db.Database.Connection.ConnectionString;
                using (var conn = new System.Data.SqlClient.SqlConnection(connectionString))
                {
                    var serverConn = new ServerConnection(conn);
                    var server = new Server(serverConn);
                    var database = server.Databases["sistan7azarrmonth55"];
                    var scripter = new Scripter(server)
                    {
                        Options =
                        {
                            IncludeIfNotExists = false,
                            ScriptData = true,
                            ScriptSchema = false
                        }
                    };
                    //db.tbUsers
                    // ایجاد فایل اسکریپت
                    string scrs = "USE [sistan7azarrmonth55]\nGO\n\nDelete from [sistan7azarrmonth55].[Usser].tbUsers\n";

                    var table = database.Tables["tbUsers"];
                    if (table.IsSystemObject == false)
                    {
                        foreach (var script in scripter.EnumScript(new[] { table.Urn }))
                        {
                            scrs += script + "\n\n";
                        }
                    }
                    // ذخیره فایل
                    string filePath = System.IO.Path.Combine(Server.MapPath("~/Content/script/"), version.FileName);
                    Directory.CreateDirectory(System.IO.Path.GetDirectoryName(filePath)); // اطمینان از وجود دایرکتوری
                    System.IO.File.WriteAllText(filePath, scrs);

                    // پیام موفقیت
                    // این خط را می‌توانید در صورت لزوم به صورت عمومی ارسال کنید.
                    // در اینجا از ViewBag استفاده کرده‌ایم تا وضعیت را به کاربر نشان دهیم
                    ViewBag.Message = "اسکریپت با موفقیت تولید شد.";
                }
            }
            catch (Exception ex)
            {
                ViewBag.Message = "خطا در تولید اسکریپت: " + ex.Message;
            }
        }

