        public JsonResult SaveFormulaData(FormulaDataViewModel data)
        {
            try
            {
                // ثبت در tbcreat_NameFrml
                var formula = new tbcreat_NameFrml
                {
                    name = data.name,
                    Datatime = DateTime.Now,
                    usr_sabt = null, // یا از Session بردارید
                    shomareh_formol = null
                };
                db.tbcreat_NameFrml.Add(formula);
                db.SaveChanges(); // گرفتن ID

                long fkNameId = formula.ID;

                foreach (var row in data.rows)
                {
                    db.tbolaviat_frml.Add(new tbolaviat_frml
                    {
                        FK_name_frml = fkNameId,
                        olaviat = string.IsNullOrWhiteSpace(row.olaviat) ? (long?)null : long.Parse(row.olaviat),
                        vorodi = string.IsNullOrWhiteSpace(row.vorodi) ? (long?)null : long.Parse(row.vorodi),
                        ghorogi = string.IsNullOrWhiteSpace(row.ghoroji) ? (long?)null : long.Parse(row.ghoroji),
                        FK_frml = string.IsNullOrWhiteSpace(row.fk_frml) ? (int?)null : int.Parse(row.fk_frml),
                        Datatime = DateTime.Now,
                        usr_sabt = null
                    });
                }

                db.SaveChanges();
                return Json(new { success = true });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }
    

