        public JsonResult GetPivotData1()
        {
            var pivotData = (
               from v in db.tbMoalefeValueFish
               where v.mlfvlfsh_Year == 1404 && v.mlfvlfsh_Month == 1 && v.FK_EXCel == null
          && v.mlfvlfsh_ID > 0
               join u in db.tbUsers on v.FK_User equals u.usr_ID
               join m in db.tbContractMoalefeDastmozdi on v.FK_Moalefe equals m.md_ID
               select new PivotCell
               {
                   UserID = u.usr_Personal_ID ?? 0,
                   MoalefeTitle = m.md_Title,
                   Value = v.mlfvlfsh_Value ?? 0
               }).ToList();

            return new JsonResult
            {
                Data = pivotData,
                JsonRequestBehavior = JsonRequestBehavior.AllowGet,
                MaxJsonLength = int.MaxValue
            };
        }



