        [HttpGet]
        public JsonResult LoadSheetsByGroupName(string groupName)
        {
            if (string.IsNullOrWhiteSpace(groupName))
                return Json(null, JsonRequestBehavior.AllowGet);

            var sheets = db.tbSheetsExtracted
                .Where(s => s.NameSaved == groupName)
                .OrderBy(s => s.SheetName)
                .ToList();

            var result = sheets.Select(s => new
            {
                s.SheetName,
                s.IsReport,
                s.SheetContent,
                s.roowCount,
                s.ColumnCount
            });

            return Json(result, JsonRequestBehavior.AllowGet);
        }


        public ActionResult SaveSheetsToDb(SheetGroupDto input)
        {
            if (input == null || string.IsNullOrWhiteSpace(input.groupName) || input.sheets == null)
                return Json(new { success = false, message = "داده نامعتبر است." });

            var existingSheets = db.tbSheetsExtracted
                .Where(x => x.NameSaved == input.groupName)
                .ToList();

            var sheetNamesFromClient = input.sheets.Select(s => s.name).ToList();

            var sheetsToDelete = existingSheets
                .Where(s => !sheetNamesFromClient.Contains(s.SheetName))
                .ToList();

            if (sheetsToDelete.Any())
                db.tbSheetsExtracted.RemoveRange(sheetsToDelete);

            foreach (var sheet in input.sheets)
            {
                bool isReport = sheet.name.StartsWith("Report_");

                int maxRow = 0;
                int maxCol = 0;
                var flattened = new List<object>();

                if (!isReport && sheet.data != null)
                {
                    for (int r = 0; r < sheet.data.Count; r++)
                    {
                        var row = sheet.data[r];
                        if (row == null) continue;

                        for (int c = 0; c < row.Count; c++)
                        {
                            var cell = row[c];
                            if (cell == null) continue;

                            if (cell.v != null || cell.f != null)
                            {
                                flattened.Add(new { r, c, v = cell.v, f = cell.f });
                                maxRow = Math.Max(maxRow, r + 1);
                                maxCol = Math.Max(maxCol, c + 1);
                            }
                        }
                    }
                }

                var existing = existingSheets.FirstOrDefault(x => x.SheetName == sheet.name);
                if (existing != null)
                {
                    if (!isReport)
                    {
                        existing.SheetContent = JsonConvert.SerializeObject(flattened);
                        existing.ColumnCount = maxCol;
                        existing.roowCount = maxRow;
                    }
                    existing.UpdatedAt = DateTime.Now;
                }
                else
                {
                    var newSheet = new tbSheetsExtracted
                    {
                        NameSaved = input.groupName,
                        SheetName = sheet.name,
                        IsReport = isReport,
                        CreatedAt = DateTime.Now
                    };

                    if (!isReport)
                    {
                        newSheet.SheetContent = JsonConvert.SerializeObject(flattened);
                        newSheet.ColumnCount = maxCol;
                        newSheet.roowCount = maxRow;
                    }

                    db.tbSheetsExtracted.Add(newSheet);
                }
            }

            db.SaveChanges();

            return Json(new { success = true, message = "ذخیره‌سازی با موفقیت انجام شد." });
        }




        [HttpPost]
        public ActionResult sabtmoshakhasat(MoshakhasatViewModel model)
        {
            try
            {
                using (SaabEntities db = new SaabEntities())
                {

                    var userid = 0;
                    var cookie_user = Request.Cookies[Utility.Base64.Base64Encode("CodeMeli")];
                    if (cookie_user != null)
                    {
                        var nationalcode = Utility.Base64.Base64Decode(cookie_user.Value);
                        var User = db.tbUsers.FirstOrDefault(p => p.usr_NationalCode.ToString() == nationalcode);
                        if (User != null)
                            userid = User.usr_ID;
                    }


                    madarek_1 madarek_1 = new madarek_1
                    {
                        time = model.FromDateMiladi,
                        name = model.FullName,
                        sharh = model.Description,
                        timesabt = DateTime.Now,
                        usrsabt = userid
                    };


                    db.madarek_1.Add(madarek_1);
                    db.SaveChanges();
                }

                return Json(new { success = true, message = "اطلاعات با موفقیت ثبت شد" });
            }
            catch (Exception ex)
            {

                System.IO.File.AppendAllText(Server.MapPath("~/App_Data/error_log.txt"),
                    DateTime.Now + " - sabtmoshakhasat: " + ex.ToString() + Environment.NewLine);

                return Json(new { success = false, message = "خطا در ثبت اطلاعات: " + ex.Message });
            }
        }
        public JsonResult GetPivotDataDynamic(long reportId)
        {
            try
            {
                var pivotDef = db.TBGOZARESHSAZ3_Creat
               .Where(x => x.FK_GOZARSH1 == reportId)
               .ToList();

                var report = db.TBGOZARESHSAZ1_Creat.FirstOrDefault(x => x.ID == reportId);
                if (report == null || string.IsNullOrWhiteSpace(report.QURY_SQL))
                    return Json(null, JsonRequestBehavior.AllowGet);
                string finalSql = AddDatabaseToSqlTables(report.QURY_SQL);

                // اجرای کوئری SQL اصلی و دریافت دیتا خام
                var rawData = ExecuteRawSql(finalSql);

                var result = new List<Dictionary<string, object>>();
                var result3 = new List<Dictionary<string, object>>();

                foreach (var def in pivotDef)
                {
                    string rowKey = def.RADIF?.Trim();
                    string colKey = def.SOTON?.Trim();
                    string valKey = def.Value?.Trim();
                    string xyx = "";
                    // گروه‌بندی بر اساس ردیف‌ها
                    // گروه‌بندی بر اساس ردیف‌ها
                    var pivot = rawData
                        .GroupBy(r =>
                        {
                            // اگر rawData شامل rowKey نباشد یا مقدارش null باشد، از یک رشته پیش‌فرض استفاده کن
                            object val = r.ContainsKey(rowKey) ? r[rowKey] : null;
                            return val?.ToString() ?? "(مقدار ردیف خالی)"; // null را با یک رشته جایگزین می‌کنیم تا Key null نباشد
                        })
                        .ToDictionary(
                            g => g.Key,
                            g => g.GroupBy(x =>
                            {
