        private string AddDatabaseToSqlTables(string sql)
        {
            // 1. گرفتن connection string
            string efConnectionString = ConfigurationManager.ConnectionStrings["SaabEntities"].ConnectionString;
            EntityConnectionStringBuilder efBuilder = new EntityConnectionStringBuilder(efConnectionString);
            string sqlConnectionString = efBuilder.ProviderConnectionString;

            // 2. گرفتن نام دیتابیس
            var builder = new SqlConnectionStringBuilder(sqlConnectionString);
            string dbName = builder.InitialCatalog;

            // 3. تزریق نام دیتابیس قبل از اسکیمای Contract (فقط جاهایی که هنوز دیتابیس نیومده)
            string pattern = @"(?<!\[\w+\]\.)\[(Contract)\]\.\[(\w+)\]";
            string replacement = $"[{dbName}].[$1].[$2]";

            string modifiedSql = Regex.Replace(sql, pattern, replacement, RegexOptions.IgnoreCase);

            return modifiedSql;
        }


        private List<Dictionary<string, object>> ExecuteRawSql(string sql)
        {
            var result = new List<Dictionary<string, object>>();

            // رشته اتصال کامل Entity Framework را دریافت می‌کنیم
            string efConnectionString = ConfigurationManager.ConnectionStrings["SaabEntities"].ConnectionString;

            // ایجاد یک EntityConnectionStringBuilder برای تجزیه رشته اتصال EF
            EntityConnectionStringBuilder efBuilder = new EntityConnectionStringBuilder(efConnectionString);

            // استخراج رشته اتصال Provider (که همان SQL Connection String است)
            string sqlConnectionString = efBuilder.ProviderConnectionString;

            // حالا از رشته اتصال SQL Server استخراج شده استفاده می‌کنیم.
            using (var conn = new SqlConnection(sqlConnectionString))
            using (var cmd = new SqlCommand(sql, conn))
            {
                conn.Open();
                using (var reader = cmd.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        var row = new Dictionary<string, object>();
                        for (int i = 0; i < reader.FieldCount; i++)
                        {
                            var columnName = reader.GetName(i);
                            var value = reader.IsDBNull(i) ? null : reader.GetValue(i);
                            row[columnName] = value;
                        }
                        result.Add(row);
                    }
                }
            }

            return result;
        }
