        public static class PivotHtmlBuilder
        {
            public static string Build(List<Dictionary<string, object>> data, string rowField, string colField, string valField)
            {
                var rowKeys = data.Select(d => d[rowField].ToString()).Distinct().OrderBy(x => x).ToList();
                var colKeys = data.Select(d => d[colField].ToString()).Distinct().OrderBy(x => x).ToList();

                var html = "<table class='table table-bordered'><thead><tr><th>" + rowField + "</th>";

                foreach (var col in colKeys)
                    html += "<th>" + col + "</th>";

                html += "</tr></thead><tbody>";

                foreach (var row in rowKeys)
                {
                    html += "<tr><td>" + row + "</td>";

                    foreach (var col in colKeys)
                    {
                        var cell = data.FirstOrDefault(d => d[rowField].ToString() == row && d[colField].ToString() == col);
                        var value = cell != null && cell.ContainsKey(valField) ? cell[valField].ToString() : "";
                        html += "<td>" + value + "</td>";
                    }

                    html += "</tr>";
                }

                html += "</tbody></table>";

                return html;
            }
        }

