        public JsonResult GetColumns(string tableName)
        {
            var type = db.GetType()
                         .GetProperties()
                         .FirstOrDefault(p => p.Name == tableName)?
                         .PropertyType.GetGenericArguments().FirstOrDefault();

            if (type == null)
                return Json(new string[0], JsonRequestBehavior.AllowGet);

            var columns = type.GetProperties()
                              .Select(p => p.Name)
                              .ToList();

            return Json(columns, JsonRequestBehavior.AllowGet);
        }
        private Dictionary<string, string> GetTableSchemasFromDb()
        {
            var result = new Dictionary<string, string>(System.StringComparer.OrdinalIgnoreCase);

            // گرفتن connection string از EF
            string efConnectionString = ConfigurationManager.ConnectionStrings["SaabEntities"].ConnectionString;
            var efBuilder = new EntityConnectionStringBuilder(efConnectionString);
            string sqlConnectionString = efBuilder.ProviderConnectionString;

            using (var conn = new SqlConnection(sqlConnectionString))
            {
                conn.Open();

                var cmd = new SqlCommand(@"
            SELECT TABLE_SCHEMA, TABLE_NAME
            FROM INFORMATION_SCHEMA.TABLES
            WHERE TABLE_TYPE = 'BASE TABLE'", conn);

                using (var reader = cmd.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        string schema = reader.GetString(0);
                        string table = reader.GetString(1);
                        result[table] = schema;
                    }
                }
            }

            return result;
        }
