            var parts = fullName.Split('.');
            return parts.Last().Replace("[", "").Replace("]", "");
        }
        [HttpGet]
        public JsonResult GetSelectedColumns(long id)
        {
            using (var db = new SaabEntities())
            {
                var records = db.TBGOZARESHSAZ2_Creat
                                .Where(x => x.FK_GOZARSH1 == id && x.SELECTED != null)
                                .Select(x => x.SELECTED)
                                .ToList();

                var columns = new List<object>();

                foreach (var row in records)
                {
                    var splitCols = row.Split(',');
                    foreach (var col in splitCols)
                    {
                        var trimmed = col.Trim();
                        var parts = trimmed.Split('.');

                        columns.Add(new
                        {
                            full = trimmed,
                            table = parts.Length > 1 ? parts[0].Replace("[", "").Replace("]", "") : "",
                            column = parts.Length > 1 ? parts[1].Replace("[", "").Replace("]", "") : parts[0]
                        });
                    }
                }

                return Json(columns, JsonRequestBehavior.AllowGet);
            }
        }

