        public string creatsqlqury(string quyry,string name)
                
        {
            try
            {
                // مرحله 1: ذخیره کوئری در جدول اول
                TBGOZARESHSAZ1_Creat q1 = new TBGOZARESHSAZ1_Creat();
                q1.QURY_SQL = quyry;
                q1.NAME = name;

                db.TBGOZARESHSAZ1_Creat.Add(q1);
                db.SaveChanges(); // تا ID تولید شود

                // مرحله 2: استخراج SELECT و WHERE
                string selectPart = "";
                string wherePart = "";

                string normalizedQuery = quyry.Replace("\n", " ").Replace("\r", " ").Trim();
                int selectIndex = normalizedQuery.IndexOf("SELECT", StringComparison.OrdinalIgnoreCase);
                int fromIndex = normalizedQuery.IndexOf("FROM", StringComparison.OrdinalIgnoreCase);
                int whereIndex = normalizedQuery.IndexOf("WHERE", StringComparison.OrdinalIgnoreCase);

                if (selectIndex != -1 && fromIndex != -1)
                {
                    selectPart = normalizedQuery.Substring(selectIndex + 6, fromIndex - (selectIndex + 6)).Trim();
                }

                if (whereIndex != -1)
                {
                    wherePart = normalizedQuery.Substring(whereIndex + 5).Trim();
                }

                // مرحله 3: جدا کردن ستون‌ها و ذخیره هرکدام در یک ردیف
                var selectItems = selectPart
                    .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries)
                    .Select(s => s.Trim())
                    .Where(s => !string.IsNullOrWhiteSpace(s));

                foreach (var col in selectItems)
                {
                    TBGOZARESHSAZ2_Creat q2 = new TBGOZARESHSAZ2_Creat();
                    q2.FK_GOZARSH1 = q1.ID;
                    q2.SELECTED = col;
                    q2.WHERE_QURY = wherePart;
                    q2.Active = true;

                    db.TBGOZARESHSAZ2_Creat.Add(q2);
                }

                db.SaveChanges();
                return "True";
            }
            catch (Exception ex)
            {
                return ex.Message;
            }
        }

        // دریافت SQL JOIN شده
        [HttpPost]
        public JsonResult GenerateSql(ReportRequestModel request)
        {
            var tableSchemas = GetTableSchemasFromDb();

            var tables = request.Tables;
            var columns = request.Columns;
            var where = request.WhereClause;

            if (tables == null || tables.Count == 0 || columns == null || columns.Count == 0)
                return Json(new { sql = "-- خطا: جدول یا ستون مشخص نشده است." });


            // پیدا کردن جدول پایه که بیشترین ارتباط را دارد
            var relations = GetTableRelations();

            var baseTable = tables
                .OrderByDescending(t =>
                    relations.Count(r =>
                        (r.FromTable == t && tables.Contains(r.ToTable)) ||
                        (r.ToTable == t && tables.Contains(r.FromTable))))
                .FirstOrDefault();


            var fromClause = $"FROM {GetQualifiedTableName(baseTable, tableSchemas)}";

            //var fromClause = $"FROM {baseTable}";
            var joinedTables = new List<string> { baseTable };
            var joinErrors = new List<string>();

            // تلاش برای JOIN کردن سایر جدول‌ها
            var pendingTables = new HashSet<string>(tables);
            pendingTables.Remove(baseTable);

            while (pendingTables.Any())
            {
                bool progress = false;

                foreach (var current in pendingTables.ToList())
                {
                    foreach (var joinedTable in joinedTables)
                    {
                        var rel = relations.FirstOrDefault(r =>
                            (r.FromTable == joinedTable && r.ToTable == current) ||
                            (r.FromTable == current && r.ToTable == joinedTable));

                        if (rel != null)
                        {
                            fromClause += $"\nINNER JOIN {GetQualifiedTableName(current, tableSchemas)} " +
                                      $"ON {GetQualifiedTableName(rel.FromTable, tableSchemas)}.{rel.FromColumn} = " +
                                      $"{GetQualifiedTableName(rel.ToTable, tableSchemas)}.{rel.ToColumn}";
                            joinedTables.Add(current);
                            pendingTables.Remove(current);
                            //fromClause += $"\nINNER JOIN {current} ON {rel.FromTable}.{rel.FromColumn} = {rel.ToTable}.{rel.ToColumn}";
                            //joinedTables.Add(current);
                            //pendingTables.Remove(current);
                            progress = true;
                            break;
                        }
                    }
                }

                if (!progress)
                {
                    foreach (var table in pendingTables)
                        joinErrors.Add($"-- ❌ نمی‌توان JOIN را برای جدول {table} تعیین کرد");

                    break;
                }
            }
            var colList = columns.Select(c => $"{GetQualifiedTableName(c.Table, tableSchemas)}.{c.Column}").ToList();
            string selectClause = $"SELECT\n  {string.Join(",\n  ", colList)}";
            string whereClause = !string.IsNullOrWhiteSpace(where) ? $"\nWHERE {where}" : "";

            string sql = $"{selectClause}\n{fromClause}\n{string.Join("\n", joinErrors)}{whereClause}";
            return Json(new { sql });
            //var colList = columns.Select(c => $"{c.Table}.{c.Column}").ToList();
            //string selectClause = $"SELECT\n  {string.Join(",\n  ", colList)}";
            //string whereClause = !string.IsNullOrWhiteSpace(where) ? $"\nWHERE {where}" : "";

            //string sql = $"{selectClause}\n{fromClause}\n{string.Join("\n", joinErrors)}{whereClause}";
            //return Json(new { sql });
        }
        private string GetQualifiedTableName(string tableName, Dictionary<string, string> tableSchemas)
        {
            if (tableSchemas.TryGetValue(tableName, out var schema))
                return $"[{schema}].[{tableName}]";
            else
                return tableName;
        }

        // تعریف روابط بین جدول‌ها
        private List<TableRelation> GetTableRelations()
        {
            var relations = new List<TableRelation>();

            var objectContext = ((IObjectContextAdapter)db).ObjectContext;
            var workspace = objectContext.MetadataWorkspace;

            // فضای مفهومی (CSpace) شامل مدل مفهومی EDM است که در آن ارتباطات تعریف شده است.
            var associationTypes = workspace.GetItems<AssociationType>(DataSpace.CSpace);

            foreach (var association in associationTypes)
            {
                if (!association.IsForeignKey)
                    continue; // فقط روابط کلید خارجی

                var constraint = association.Constraint;

                var fromRole = constraint.FromRole;
                var toRole = constraint.ToRole;

                var fromTable = fromRole.Name; // این معمولا نام نقش در ارتباط است
                var toTable = toRole.Name;

                var fromProperties = constraint.FromProperties;
                var toProperties = constraint.ToProperties;

                for (int i = 0; i < fromProperties.Count; i++)
                {
                    relations.Add(new TableRelation
                    {
                        FromTable = fromTable,
                        FromColumn = fromProperties[i].Name,
                        ToTable = toTable,
                        ToColumn = toProperties[i].Name
                    });
                }
            }

            return relations;
        }


        public class ReportRequestModel
        {
            public List<string> Tables { get; set; }
            public List<ColumnSelection> Columns { get; set; }
            public string WhereClause { get; set; }
        }

        public class ColumnSelection
        {
            public string Table { get; set; }
            public string Column { get; set; }
        }

        public class TableRelation
        {
            public string FromTable { get; set; }
            public string FromColumn { get; set; }
            public string ToTable { get; set; }
            public string ToColumn { get; set; }
        }

        public JsonResult RunReport(string table, List<string> columns, string year, string month)
        {
            var selectedCols = string.Join(",", columns.Select(c => $"A.{c}"));
            var sql = $@"
SELECT {selectedCols}
FROM Salary.tbMoalefeValueFish A
INNER JOIN Usser.tbUsers B ON A.FK_User = B.usr_ID
INNER JOIN Contract.tbContractMoalefeDastmozdi C ON A.FK_Moalefe = C.md_ID
WHERE A.mlfvlfsh_Year = @year AND A.mlfvlfsh_Month = @month";

            var data = db.Database.SqlQuery<Dictionary<string, object>>(sql,
                new SqlParameter("@year", year),
                new SqlParameter("@month", month)).ToList();

            return Json(data);
        }


