        // ستون‌های جدول + روابط ناوبری (navigation properties)
        public JsonResult GetTableDetails(string tableName)
        {
            var prop = db.GetType().GetProperties()
                         .FirstOrDefault(p => p.Name == tableName);

            if (prop == null)
                return Json(null, JsonRequestBehavior.AllowGet);

            var type = prop.PropertyType.GetGenericArguments().FirstOrDefault();
            if (type == null)
                return Json(null, JsonRequestBehavior.AllowGet);

            var columns = type.GetProperties()
                .Where(p => p.PropertyType.IsValueType || p.PropertyType == typeof(string))
                .Select(p => p.Name).ToList();

            var navigations = type.GetProperties()
                .Where(p => !p.PropertyType.IsValueType && p.PropertyType != typeof(string))
                .Select(p => new
                {
                    NavigationProperty = p.Name,
                    RelatedEntity = p.PropertyType.Name
                }).ToList();

            return Json(new { columns, navigations }, JsonRequestBehavior.AllowGet);
        }

        // اجرای گزارش ساده با انتخاب ستون‌ها و فیلتر (اینجا بدون JOIN پیچیده هنوز)
        
        public class ReportColumn
        {
            public string TableName { get; set; }
            public string ColumnName { get; set; }
        }

        [HttpPost]
        public JsonResult RunDynamicReport(List<ReportColumn> selectedColumns)
        {
            if (selectedColumns == null || !selectedColumns.Any())
                return Json(new { error = "هیچ ستونی انتخاب نشده است" });

            string mainTable = selectedColumns.First().TableName;

            // شبیه‌سازی JOIN ساده بین جدول اصلی و جداول مرتبط
            var tableAliases = new Dictionary<string, string>();
            int aliasIndex = 0;
            string GetAlias(string table)
            {
                if (!tableAliases.ContainsKey(table))
                    tableAliases[table] = "t" + (aliasIndex++);
                return tableAliases[table];
            }

            var selectedColsSql = selectedColumns
                .Select(sc => $"{GetAlias(sc.TableName)}.[{sc.ColumnName}]")
                .ToList();

            var fromClause = $"{mainTable} {GetAlias(mainTable)}";
            var joinClauses = new List<string>();

            // فرض کنیم نام FK مثل: FK_User به User وصل می‌شود
            foreach (var relTable in selectedColumns.Select(c => c.TableName).Distinct().Where(t => t != mainTable))
            {
                // نمونه اولیه فقط JOIN ON FK_XXX = PK_XXX
                string mainAlias = GetAlias(mainTable);
                string relAlias = GetAlias(relTable);

                string fk = $"FK_{relTable}";
                string pk = relTable + "ID";

                joinClauses.Add($"LEFT JOIN {relTable} {relAlias} ON {mainAlias}.[{fk}] = {relAlias}.[{pk}]");
            }

            string sql = $"SELECT {string.Join(",", selectedColsSql)} FROM {fromClause} {string.Join(" ", joinClauses)}";

            var result = db.Database.SqlQuery<Dictionary<string, object>>(sql).ToList();

            return Json(result);
        }

